// ── Gating ──
// Strong phrases mean the rider is asking about rules on their own; weak topic words need a rules word next to them,
// so "race fuel jetting" or "the rear sounds harsh" stay with tuning.
const STRONG=new RegExp('\\b('+[
 "rule ?books?","race rules","ama rules","supplemental rules","sound (test|check|limit|level|control)","decibels?","\\d{2,3} ?db","db ?\\/?a\\b",
 "2[- ]?met(er|re) (max|test)","tech(nical)? (inspection|check|line)","pass(ed|ing)? tech","number plates?","plate colou?rs?","plate backgrounds?",
 "background colou?rs?","spec fuel","fuel (spec|rules?|test)","race[- ]legal","legal (for|at|in) (ama|racing|the race|the national|loretta|supercross|pro)",
 "loretta","area qualifiers?","regional championships?","amateur nationals?","road to (supercross|sx)","smx next","250 ?(sx )?(east|west)","eligib\\w*",
 "homologat\\w*","transponders?","chest (and back )?protect\\w*","back protector","roost (guard|deflector)","helmet (cert\\w*|standards?|rating|rules?)",
 "snell","ece ?22","eject (system|helmet)","kill (switch|button)","lanyard","supermini","schoolboy","mini ?sr","limited class(es)?",
 "(a|b|c|vet|senior|masters|women'?s?|girls|college|pro sport|micro) class(es)?","arenacross","claiming (rule|price)","claim (a|his|her|their|my) bike","rpv","pro point",
 "regionals?","how many motos","moto format",
 // flags and on-track
 "(red[- ]?cross|yellow|blue|black|white|green|checkered|chequered|red) flags?","(who wins|break(s|ing)?) (a|the) tie","tied (on|in|for) (points|the overall|overall)","flag (rules?|penalt\\w*)","flaggers?","jump(ed|ing|s)? (the|a) (gate|start)",
 "gate jump\\w*","false starts?","30[- ]?second (card|board|sign)","rubber band start","staggered (re)?starts?","gate picks?","starting blocks?",
 "track cut\\w*","cut(ting|s)? the (track|course)","course cutting","outside (assistance|help)",
 // scoring, protests, penalties
 "protests?","appeal (a|the|my|an|his|her) \\w+","appeals? (process|fee|board|deadline)","file an appeal","disqualif\\w*","tie ?break\\w*",
 "how (are|is|do) (the |they )?(motos?|overalls?|races?|points|results|scoring|playoffs?)( get)? (scored|calculated|figured|decided|done|work)",
 "points? (system|scale|table|schedule|structure)","championship points","playoffs?","triple crown","lcq","last chance qualifier","consolation race",
 "career numbers?","national numbers?","license penalty points?","penalty points?",
 // entry, minors, safety
 "ama (membership|card)","one[- ]event pass","minor('?s)? (release|waiver)","parental consent","notari[sz]\\w*","release (form|waiver)","concussion (policy|rules?)",
 "lightning (rule|policy)","(race|racing|ride|riding) without (me|a parent|(his|her|their) (parents?|mom|dad))","(grandma|grandpa|grandparents?|uncle|aunt|coach|a friend) (can |could )?(take|bring)s? (my|our|him|her|them)",
 // pits and series
 "pit vehicles?","pit (bike|cart)s? (allowed|rules?|permit)","paddock (rules?|speed)","fire extinguisher","mechanics? area","mini ?o'?s","winter ?am",
 "tristar","partzilla","mid[- ]?south","wmx","pro[- ]?am","pro sport","250 licen[cs]e","hare scrambles? rules?",
].join('|')+')\\b','i');
const RULE_CTX=/\b(legal|illegal|allowed|permitted|eligible|required|requires?|requirements?|mandatory|banned|rules?|ama|sanction(ed)?|series|tech|inspection|disqualif\w*|dq|penalt\w*|penaliz\w*)\b|\bcan (i|he|she|we|they|my \w+) (race|run|enter|ride)\b|\b(which|what) class\b|\bhow old\b|\bwhat happens if\b|\bwhat does (a|the) \w+ (flag|board|card) mean\b/i;
const TOPIC_WORD=/\b(class(es)?|fuel|gas|plates?|numbers?|helmets?|boots|gear|chest|neck brace|exhaust|pipe|muffler|silencer|loud|age|qualif\w*|motos?|tires?|footpegs?|pegs|levers?|throttle|brakes?|knobs|two[- ]?strokes?|2[- ]?strokes?|four[- ]?strokes?|4[- ]?strokes?|cc|250|450|125|85|65|50|flags?|gate|starts?|scor\w*|points?|protest|pits?|paddock|pit bikes?|membership|minor|release|waiver|licen[cs]e|hare scrambles?|displacement|transponders?|cutting|mxgp|mx2|fim)\b/i;
const FOLLOW_UP=/^(and|also|what about|how about|same for|what if|is that|does that|do they|does it|for (a|an|the|my))\b/i;

const TOPIC_WORDS:Record<RaceRuleTopic,RegExp>={
 classes:/\b(class(es)?|supermini|schoolboy|mini ?sr|micro|vet|senior|masters|women|girls|college|junior|limited|pro sport|displacement|cc|two[- ]?stroke|2[- ]?stroke|four[- ]?stroke|4[- ]?stroke|50|51|65|85|112|125|150|250|450|weight|move up|mxgp|mx2|wmx)\b/i,
 eligibility:/\b(eligib\w*|licen[cs]e|age|old|turn pro|road to supercross|smx next|east|west|classification|rpv|pro point|(a|b|c) class|move up|pro[- ]?am|advancement|foreign|cash|prize)\b/i,
 entry:/\b(members?(hip)?|ama card|one[- ]event|minors?|parents?|guardian|release|waiver|notar\w*|consent|entry|entries|enter|register\w*|registration|sign[- ]?up|insurance|concussion|head injur\w*|lightning|weather|storm|refund)\b/i,
 sound:/\b(sound|loud|db|decibels?|muffler|silencer|exhaust|pipe|quiet|packing|end ?cap|insert)\b/i,
 fuel:/\b(fuel|gas|gasoline|octane|oxygen\w*|ethanol|e10|race gas|pump|premix|additive)\b/i,
 tech:/\b(tech|inspection|kill|lanyard|levers?|ball ends?|bar ends?|throttle|brakes?|pegs?|footpegs?|chain|sprocket|guard|tires?|knobs|transponder|weigh\w*|impound|teardown|electronics?|traction control|camera|spark arr?est\w*|hare scrambles?)\b/i,
 plates:/\b(plates?|numbers?|backgrounds?|colou?rs?|graphics|jersey number)\b/i,
 gear:/\b(helmet|snell|ece|chest|back protector|roost|neck|brace|boots?|gloves?|goggles?|jersey|pants|gear|protect\w*)\b/i,
 flags:/\b(flags?|red ?cross|yellow|blue|checkered|chequered|lights?|cut\w*|outside (help|assistance)|help|assist\w*|marshals?|passing|triples?|doubles?)\b/i,
 starts:/\b(starts?|starting|gate|gates|30[- ]?second|card|board|sideways|staging|groom\w*|blocks?|rubber band|stagger\w*|sighting lap|practice)\b/i,
 scoring:/\b(scor\w*|points?|ties?|tied|tie ?break\w*|overall|dnf|dns|dq|results?|playoffs?|champion\w*|lcq|heats?|main event|mains|consolation|triple crown|seed\w*|red flag|restart\w*|format|standings|motos?)\b/i,
 protests:/\b(protest\w*|appeal\w*|claim\w*|teardown|penalt\w*|penaliz\w*|disqualif\w*|dq|suspended|fines?|referee|race direction|conduct|fight\w*|reckless)\b/i,
 paddock:/\b(pits?|paddock|pit (bikes?|vehicles?)|golf carts?|side ?by ?side|sxs|fire extinguisher|mechanics?|speed limit|mph|pets?|camping)\b/i,
 qualifying:/\b(loretta\w*|qualif\w*|aq|regionals?|nationals?|advance\w*|transfer|alternates?|power ranking)\b/i,
 arenacross:/\b(arenacross|arena|partzilla|indoor|throttlecross|gt arenacross|tristar|mid-?south|ax|lincoln trail)\b/i,
 local:/\b(florida|gatorback|unlimited sports|local|club|district|mini o'?s|winter am|tristar|mid-?south|dade city|ww ranch|diamondback|okeechobee|orlando)\b/i,
};
const PRO=/\b(pro|pros|supercross|sx|smx|pro motocross|450sx|250sx|450mx|250mx|factory|privateer|road to supercross|east|west|license|playoffs?|mxgp|mx2|fim|wmx|grand prix)\b/i;
const AMATEUR=/\b(amateur|youth|kids?|son|daughter|mini|minis|loretta\w*|aq|regionals?|vet|senior|masters|limited|schoolboy|supermini|girls|college|local|club|(a|b|c) class|50cc|51|65|85|112|125 ?c|mini o'?s|winter am|stacyc)\b/i;

/** Max size of the returned JSON, about 2.3k tokens at four characters a token. */
export const RACE_RULES_MAX_CHARS=9200;

const clean=(s:string)=>s.replace(/rules? of thumb/gi,'').replace(/sounds? (like|good|right|off|weird|harsh)/gi,'');
export function isRaceRulesQuestion(text:string):boolean{
 const t=clean(text);
 return STRONG.test(t)||(RULE_CTX.test(t)&&TOPIC_WORD.test(t));
}

/** Compact race-rules section for Ask BAK, or null when the conversation is not about race rules.
 * `history` is earlier rider messages, oldest first; a short follow-up inherits a rules conversation from them. */
export function raceRules(message:string,history:string[]=[]):object|null{
 const recent=history.slice(-3);
 let text=message;
 if(!isRaceRulesQuestion(message)){
  const short=message.trim().length<=90&&(FOLLOW_UP.test(message.trim())||TOPIC_WORD.test(clean(message)));
  if(!(short&&recent.some(isRaceRulesQuestion)))return null;
  text=[...recent,message].join(' \n ');
 }
 const t=clean(text),m=clean(message);
 const keys=Object.keys(TOPIC_WORDS) as RaceRuleTopic[];
 const hits=(re:RegExp,s:string)=>Math.min(3,(s.match(new RegExp(re.source,'gi'))??[]).length);
 // The current message counts double; earlier messages only carry the topic of a follow-up.
 const weight=Object.fromEntries(keys.map(k=>[k,2*hits(TOPIC_WORDS[k],m)+(t===m?0:hits(TOPIC_WORDS[k],t))])) as Record<RaceRuleTopic,number>;
 const topics=keys.filter(k=>weight[k]>0).sort((a,b)=>weight[b]-weight[a]);
 const pro=PRO.test(t),am=AMATEUR.test(t);
 // An item's own keywords (a series, class or flag it is about) lift it above the rest of its topic,
 // and let it in even when the question's topic words point elsewhere.
 const kwHit=(r:RaceRule)=>r.kw?(r.kw.test(m)?2:r.kw.test(t)?1:0):0;
 const score=(r:RaceRule)=>{
  const k=kwHit(r);
  let s=topics.includes(r.topic)?weight[r.topic]*2:(r.core&&!topics.length?4:0);
  s+=k===2?6:k===1?3:0;
  if(r.who==='all')s+=1;else if((r.who==='pro'&&pro)||(r.who==='amateur'&&am))s+=3;else if(pro!==am)s-=3;
  if(r.core)s+=1;
  return s;
 };
 const ranked=RACE_RULES.map((r,i)=>({r,i,s:score(r)}))
  .filter(x=>(topics.length?topics.includes(x.r.topic)||kwHit(x.r)===2:x.r.core||kwHit(x.r)===2)&&x.s>0)
  .sort((a,b)=>b.s-a.s||a.i-b.i);
 const shown=new Set(ranked.map(x=>x.r.topic));
 const unknown=raceRuleUnknowns.filter(u=>topics.includes(u.topic)||shown.has(u.topic)).map(({topic,year,what})=>({topic,year,what}));
 const out={version:RACE_RULES_VERSION,as_of:RACE_RULES_AS_OF,
  boundary:'Race rules BAK summarized in its own words from published rulebooks; not the official text. Each item carries the year of the book it came from and the body that publishes it. Rules change every season and clubs and series add supplemental rules, so always tell the rider to confirm with the current rulebook and the series or club running the race before race day; the tech inspector and referee have the final say. Items marked with a caution come from an older edition or a secondary report: say so. Anything under unknown, or not listed here, is unknown: say BAK does not have it rather than guessing a number.',
  topics:topics.length?topics:['overview'],
  items:[] as Omit<RaceRule,'core'|'who'|'id'|'kw'>[],
  unknown};
 // Unknowns ride along only while they fit; items come first.
 while(out.unknown.length&&JSON.stringify(out).length>RACE_RULES_MAX_CHARS*0.25)out.unknown.pop();
 for(const {r} of ranked){
  const {core:_c,who:_w,id:_i,kw:_k,...item}=r;
  out.items.push(item);
  if(JSON.stringify(out).length>RACE_RULES_MAX_CHARS){out.items.pop();}
 }
 if(!out.items.length)return null;
 return out;
}
